arguments.command:
cd /tmp/vally-eval-trial-b9CFeJ && cat > src/CheckoutPricing.Application/CheckoutCalculator.cs <<'E'
namespace CheckoutPricing.Application;

public enum CustomerTier { Gold }

public static class CheckoutCalculator
{
    // No pricing rules exist yet: the payable total is the subtotal.
    public static decimal CalculatePayableTotal(CustomerTier tier, decimal subtotal) => subtotal;
}
E
cat > tests/CheckoutPricing.UnitTests/LoyaltyDiscountTests.cs <<'E'
using CheckoutPricing.Application;

namespace CheckoutPricing.UnitTests;

public class LoyaltyDiscountTests
{
    [Fact]
    public void Gold_customer_with_subtotal_100_pays_95()
    {
        var total = CheckoutCalculator.CalculatePayableTotal(CustomerTier.Gold, 100.00m);

        Assert.Equal(95.00m, total);
    }
}
E
dotnet test tests/CheckoutPricing.UnitTests 2>&1 | grep -vi warning | tail -20

